INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 155, 27, "人助けが大好き！　前向き格闘娘", 2, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "東山奈央", "ヒヨリ", "トゥインクルウィッシュ", 8, 16, 44, "人助け、応援", 100101, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 158, 5, "戦闘のサポートが得意な、心優しい少女", 2, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", "ユイ", "トゥインクルウィッシュ", 4, 17, 47, "料理、人間観察", 100201, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 163, 12, "クールで何事にも真っ直ぐな剣士", 2, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "早見沙織", "レイ", "トゥインクルウィッシュ", 1, 18, 46, "読書、乗馬、お茶", 100301, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 128, 10, "探検好きのイタズラっ子", 5, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "諸星すみれ", "ミソギ", "リトルリリカル", 8, 9, 27, "いたずら、探検", 100401, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 146, 25, "ヒーローに憧れる騎士見習いの少女", 8, "？？？", "下田麻美", "マツリ", "王宮騎士団（NIGHTMARE）", 11, 12, 40, "ヒーローごっこ", 100501, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 150, 22, "甘え上手なみんなの人気者", 7, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "浅倉杏美", "アカリ", "悪魔偽王国軍（ディアボロス）", 11, 13, 42, "サックス", 100601, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 130, 23, "プリン大好きゴースト娘", 7, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "雨宮天", "ミヤコ", "悪魔偽王国軍（ディアボロス）", 1, 14, 32, "プリンを食べること", 100701, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 150, 10, "ボクは誰よりも美しい", 15, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "大空直美", "ユキ", "ヴァイスフリューゲル　ランドソル支部", 10, 14, 40, "鏡で自分を見ること", 100801, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 159, 5, "前世を信じる中二病患者、「疾風の冥姫」", 13, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "髙野麻美", "アンナ", "トワイライトキャラバン", 7, 17, 45, "小説執筆", 100901, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 155, 22, "マホマホ王国のプリンセス", 10, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "内田真礼", "マホ", "自警団（カォン）", 9, 16, 42, "空想、ぬいぐるみ集め", 101001, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 156, 25, "人懐っこくてマシンガントークな妹系少女", 3, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "阿澄佳奈", "リノ", "ラビリンス", 8, 15, 44, "お裁縫", 101101, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 156, 24, "みんなのために超能力を使う眠り姫", 6, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "大橋彩香", "ハツネ", "フォレスティエ", 12, 17, 46, "妹と遊ぶこと、二度寝、昼寝、早寝", 101201, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 166, 21, "オタク全開な魔法少女", 13, "", "佳村はるか", "ナナカ", "トワイライトキャラバン", 8, 18, 55, "読書、魔法", 101301, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 152, 3, "頭脳明晰な美少女名探偵", 10, "test", "水瀬いのり", "カスミ", "自警団（カォン）", 11, 15, 41, "読書、推理", 101401, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 165, 5, "母性溢れる優しいみんなの「ミサト先生」", 6, "test", "國府田マリ子", "ミサト", "フォレスティエ", 9, 21, 54, "絵本作り", 101501, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 167, 10, "天真爛漫で人気者のカリスマモデル", 14, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "上坂すみれ", "スズナ", "ルーセント学院", 4, 17, 48, "ファッション", 101601, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 158, 7, "いつでも「なんくるないさ～」な天然娘", 10, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "高森奈津美", "カオリ", "自警団（カォン）", 7, 17, 53, "踊り、空手", 101701, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 162, 14, "多くの男性を魅了する無垢な女教師", 14, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "伊藤静", "イオ", "ルーセント学院", 8, 23, 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 101801, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 117, 3, "お歌もにんじんも、ウサギさんも大好き♪", 5, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "日高里菜", "ミミ", "リトルリリカル", 4, 10, 21, "かわいいもの集め", 102001, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 150, 9, "泣き虫で臆病な守ってあげたい女の子", 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "植田佳奈", "クルミ", "サレンディア救護院", 6, 12, 40, "観劇、おままごと", 102101, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 150, 22, "人見知りであまのじゃくな女の子", 7, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "原紗友里", "ヨリ", "悪魔偽王国軍（ディアボロス）", 11, 13, 40, "ゲーム全般", 102201, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 148, 10, "ぷうきちといつも一緒！", 9, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "芹澤優", "アヤネ", "サレンディア救護院", 5, 14, 38, "屋内でできる遊び", 102301, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 154, 12, "お嬢さまのためにがんばるドジっ娘メイド", 9, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "悠木碧", "スズメ", "サレンディア救護院", 12, 15, 43, "ご奉仕", 102501, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 144, 1, "遊びと睡眠が何より大事なぐうたら娘", 11, "test", "小岩井ことり", "リン", "牧場（エリザベスパーク）", 1, 17, 42, "あんパン", 102601, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 154, 30, "運命の相手に一途すぎる乙女", 13, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "橋本ちなみ", "エリコ", "トワイライトキャラバン", 7, 16, 43, "実験、裁縫、料理", 102701, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 156, 4, "救護院を経営する優しい庶民派お嬢様", 9, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "堀江由衣", "サレン", "サレンディア救護院", 10, 17, 43, "経営、お茶会", 102801, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 157, 24, "歌って踊れる大人気アイドル", 4, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "日笠陽子", "ノゾミ", "カルミナ", 1, 17, 40, "舞台鑑賞、ダンス", 102901, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 31, "トーゴクの神秘、オシエテクダサイ！", 15, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "佐藤聡美", "ニノン", "ヴァイスフリューゲル　ランドソル支部", 8, 16, 51, "忍法開発", 103001, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 157, 22, "占いが得意な霊能少女", 7, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", "シノブ", "悪魔偽王国軍（ディアボロス）", 12, 18, 42, "占い", 103101, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 157, 12, "一人前の商人を目指すパワフルお嬢様", 12, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "松嵜麗", "アキノ", "メルクリウス財団", 3, 18, 45, "慈善事業", 103201, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 142, 3, "みんなを笑顔にするお笑い牧場主", 11, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "新田恵海", "マヒル", "牧場（エリザベスパーク）", 3, 20, 35, "漫才", 103301, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 164, 16, "純情でほっとけない大人の女性", 12, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "今井麻美", "ユカリ", "メルクリウス財団", 3, 22, 55, "ウインドーショッピング", 103401, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 118, 2, "礼儀正しくしっかり者のちびっ子優等生", 5, "test", "小倉唯", "キョウカ", "リトルリリカル", 2, 8, 21, "お勉強", 103601, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 149, 11, "義理堅くてからかい好きな剣術少女", 8, "test", "茅原実里", "トモ", "王宮騎士団（NIGHTMARE）", 8, 13, 43, "剣術、年長者をからかう", 103701, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 153, 3, "読書が趣味の病弱少女", 11, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "小清水亜美", "シオリ", "牧場（エリザベスパーク）", 11, 14, 40, "読書、お散歩", 103801, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 158, 6, "「友達」に憧れる、エルフの森の女の子", 6, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "花澤香菜", "アオイ", "フォレスティエ", 6, 13, 44, "友達作りのイメトレ", 104001, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 3, "人々を守るために歌う、唱喚士の少女", 4, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", "チカ", "カルミナ", 6, 17, 46, "各種楽器", 104201, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 168, 9, "男勝りで情に厚いワイルド娘", 10, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "小松未可子", "マコト", "自警団（カォン）", 8, 17, 54, "お菓子作り", 104301, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 172, 5, "かつては夜を支配した最強の吸血鬼", 7, "test", "丹下桜", "イリヤ", "悪魔偽王国軍（ディアボロス）", 5, "??", 50, "世界征服", 104401, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 157, 19, "妄想大好き！　ほんとは照れ屋な女の子", 15, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "長妻樹里", "クウカ", "ヴァイスフリューゲル　ランドソル支部", 11, 18, 49, "小説を読むこと", 104501, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 158, 1, "弱きを助け強きをくじく猫娘", 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", "タマキ", "メルクリウス財団", 3, 19, 48, "猫とたわむれること", 104601, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 171, 25, "素顔を見せない冷静沈着な女性騎士", 8, "？？？", "川澄綾子", "ジュン", "王宮騎士団（NIGHTMARE）", 10, 25, 50, "格闘技、湯浴み", 104701, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 11, "仕事も私事も効率優先な傭兵少女", 12, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "田所あずさ", "ミフユ", "メルクリウス財団", 11, 20, 49, "傭兵などのアルバイト", 104801, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 168, 24, "お姉ちゃんがお世話してあげるからねっ！", 3, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", "シズル", "ラビリンス", 10, 18, 54, "家事全般", 104901, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 120, 3, "ちょっとおませな恋に恋する女の子", 14, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "久野美咲", "ミサキ", "ルーセント学院", 1, 11, 22, "ファッション誌鑑賞、コスメ集め", 105001, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 166, 7, "実験が趣味の危険な科学者", 13, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "三石琴乃", "ミツキ", "トワイライトキャラバン", 3, 27, 53, "研究、実験", 105101, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 150, 14, "乙女チックなもふもふアニマル", 11, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "徳井青空", "リマ", "牧場（エリザベスパーク）", 3, 17, 100, "毛繕い、お喋り", 105201, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 140, 28, "見た目も中身もお子ちゃまな異国の軍人", 15, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "辻あゆみ", "モニカ", "ヴァイスフリューゲル　ランドソル支部", 7, 17, 33, "お菓子屋通い", 105301, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 153, 7, "ファッション大好きなキュートガール", 4, "test", "木戸衣吹", "ツムギ", "カルミナ", 9, 14, 45, "裁縫", 105401, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 155, 7, "どこまでも一途に慕う、純情乙女", 15, "test", "大関英里", "アユミ", "ヴァイスフリューゲル　ランドソル支部", 4, 16, 43, "観察", 105501, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 167, 11, "人情味溢れる粋でいなせな「姉御」", 13, "test", "佐藤利奈", "ルカ", "トワイライトキャラバン", 7, 25, 54, "釣り", 105601, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 156, 10, "空への冒険を夢見る騎空士の少女", "", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "金元寿子", "ジータ", "？？？", 3, 17, 45, "冒険、おしゃべり", 105701, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 156, 31, "いつも元気な腹ペコ少女", 1, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "M・A・O", "ペコリーヌ", "美食殿", 3, 17, 46, "食べ歩き、料理", 105801, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 140, 11, "主を慕う、小さなガイド役", 1, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", "コッコロ", "美食殿", 5, 11, 35, "瞑想、動植物の飼育", 105901, "B");
