INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 152, 2, "行き倒れの謎のネコミミ魔法使い", 1, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "立花理香", "キャル（サマー）", "美食殿", 9, 14, 39, "猫と遊ぶ", 107801, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 158, 1, "弱きを助け強きをくじく猫娘", 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", "タマキ（サマー）", "メルクリウス財団", 3, 19, 48, "猫とたわむれること", 107901, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 11, "仕事も私事も効率優先な傭兵少女", 12, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "田所あずさ", "ミフユ（サマー）", "メルクリウス財団", 11, 20, 49, "傭兵などのアルバイト", 108001, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 157, 22, "占いが得意な霊能少女", 7, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", "シノブ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", 12, 18, 42, "占い", 108101, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 130, 23, "プリン大好きゴースト娘", 7, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "雨宮天", "ミヤコ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", 1, 14, 32, "プリンを食べること", 108201, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 120, 3, "ちょっとおませな恋に恋する女の子", 14, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "久野美咲", "ミサキ（ハロウィン）", "ルーセント学院", 1, 11, 22, "ファッション誌鑑賞、コスメ集め", 108301, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 3, "人々を守るために歌う、唱喚士の少女", 4, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", "チカ（クリスマス）", "カルミナ", 6, 17, 46, "各種楽器", 108401, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 150, 9, "泣き虫で臆病な守ってあげたい女の子", 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "植田佳奈", "クルミ（クリスマス）", "サレンディア救護院", 6, 12, 40, "観劇、おままごと", 108501, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 148, 10, "ぷうきちといつも一緒！", 9, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "芹澤優", "アヤネ（クリスマス）", "サレンディア救護院", 5, 14, 38, "屋内でできる遊び", 108601, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 155, 27, "人助けが大好き！　前向き格闘娘", 2, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "東山奈央", "ヒヨリ（ニューイヤー）", "トゥインクルウィッシュ", 8, 16, 44, "人助け、応援", 108701, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 158, 5, "戦闘のサポートが得意な、心優しい少女", 2, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", "ユイ（ニューイヤー）", "トゥインクルウィッシュ", 4, 17, 47, "料理、人間観察", 108801, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 163, 12, "クールで何事にも真っ直ぐな剣士", 2, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "早見沙織", "レイ（ニューイヤー）", "トゥインクルウィッシュ", 1, 18, 46, "読書、乗馬、お茶", 108901, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 154, 30, "運命の相手に一途すぎる乙女", 13, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "橋本ちなみ", "エリコ（バレンタイン）", "トワイライトキャラバン", 7, 16, 43, "実験、裁縫、料理", 109001, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 168, 24, "お姉ちゃんがお世話してあげるからねっ！", 3, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", "シズル（バレンタイン）", "ラビリンス", 10, 18, 54, "家事全般", 109101, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 156, 1, "英霊と契約を結んだマナリアの天才王女", "", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "日笠陽子", "アン", "？？？", 12, 17, 55, "読書", 109201, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 144, 4, "マナリア魔法学院の新入生", "", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "こやまきみこ", "ルゥ", "？？？", 2, 16, 45, "食べること、眠ること", 109301, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "半人半竜", 167, 3, "人を超越した力を有す心優しい竜姫", "", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "福原綾香", "グレア", "？？？", 11, 17, 67, "ピアノ", 109401, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 157, 19, "妄想大好き！　ほんとは照れ屋な女の子", 15, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "長妻樹里", "クウカ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 11, 18, 49, "小説を読むこと", 109501, "AB");
