INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 157, 12, "一人前の商人を目指すパワフルお嬢様", 12, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "松嵜麗", "アキノ（クリスマス）", "メルクリウス財団", 3, 18, 45, "慈善事業", 114401, "AB");
