INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 140, 11, "主を慕う、小さなガイド役", 1, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "伊藤美来", "コッコロ（儀装束）", "美食殿", 5, 11, 35, "瞑想、動植物の飼育", 115501, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 158, 5, "戦闘のサポートが得意な、心優しい少女", 2, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "種田梨沙", "ユイ（儀装束）", "トゥインクルウィッシュ", 4, 17, 47, "料理、人間観察", 115601, "O");
