INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 150, 14, "乙女チックなもふもふアニマル", 11, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "徳井青空", "リマ（シンデレラ）", "牧場（エリザベスパーク）", 3, 17, 100, "毛繕い、お喋り", 115801, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 168, 9, "男勝りで情に厚いワイルド娘", 10, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "小松未可子", "マコト（シンデレラ）", "自警団（カォン）", 8, 17, 54, "お菓子作り", 115901, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 155, 22, "マホマホ王国のプリンセス", 10, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "内田真礼", "マホ（シンデレラ）", "自警団（カォン）", 9, 16, 42, "空想、ぬいぐるみ集め", 116001, "O");
