INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 158, 1, "弱きを助け強きをくじく猫娘", 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "沼倉愛美", "タマキ（作業服）", "メルクリウス財団", 3, 19, 48, "猫とたわむれること", 116801, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 11, "仕事も私事も効率優先な傭兵少女", 12, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "田所あずさ", "ミフユ（作業服）", "メルクリウス財団", 11, 20, 49, "傭兵などのアルバイト", 116901, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 154, 30, "運命の相手に一途すぎる乙女", 13, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "橋本ちなみ", "エリコ（サマー）", "トワイライトキャラバン", 7, 16, 43, "実験、裁縫、料理", 117001, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 168, 24, "お姉ちゃんがお世話してあげるからねっ！", 3, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "生天目仁美", "シズル（サマー）", "ラビリンス", 10, 18, 54, "家事全般", 117101, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 157, 24, "歌って踊れる大人気アイドル", 4, "", "日笠陽子", "ノゾミ（サマー）", "カルミナ", 1, 17, 40, "舞台鑑賞、ダンス", 117201, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 3, "人々を守るために歌う、唱喚士の少女", 4, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", "チカ（サマー）", "カルミナ", 6, 17, 46, "各種楽器", 117301, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 153, 7, "ファッション大好きなキュートガール", 4, "", "木戸衣吹", "ツムギ（サマー）", "カルミナ", 9, 14, 45, "裁縫", 117401, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 166, 7, "実験が趣味の危険な科学者", 13, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "三石琴乃", "ミツキ（オーエド）", "トワイライトキャラバン", 3, 27, 53, "研究、実験", 117501, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "エルフ", 150, 10, "ボクは誰よりも美しい", 15, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "大空直美", "ユキ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 10, 14, 40, "鏡で自分を見ること", 117601, "AB");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "獣人族", 158, 7, "いつでも「なんくるないさ～」な天然娘", 10, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "高森奈津美", "カオリ（ハロウィン）", "自警団（カォン）", 7, 17, 53, "踊り、空手", 117701, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 163, 31, "トーゴクの神秘、オシエテクダサイ！", 15, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "佐藤聡美", "ニノン（ハロウィン）", "ヴァイスフリューゲル　ランドソル支部", 8, 16, 51, "忍法開発", 117801, "O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 167, 10, "天真爛漫で人気者のカリスマモデル", 14, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "上坂すみれ", "スズナ（ハロウィン）", "ルーセント学院", 4, 17, 48, "ファッション", 117901, "O");
