INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 142, 3, "みんなを笑顔にするお笑い牧場主", 11, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "新田恵海", "マヒル（クリスマス）", "牧場（エリザベスパーク）", 3, 20, 35, "漫才", 119201, "B");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "ヒューマン", 156, 25, "人懐っこくてマシンガントークな妹系少女", 3, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "阿澄佳奈", "リノ（クリスマス）", "ラビリンス", 8, 15, 44, "お裁縫", 119301, "A");
