INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 159, 5, "前世を信じる中二病患者、「疾風の冥姫」", 13, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "髙野麻美", "アンナ（パイレーツ）", "トワイライトキャラバン", 7, 17, 45, "小説執筆", 121901, "A");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, "魔族", 157, 22, "占いが得意な霊能少女", 7, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "大坪由佳", "シノブ（パイレーツ）", "悪魔偽王国軍（ディアボロス）", 12, 18, 42, "占い", 122001, "AB");
